//! MG-04's oracle: testdata/protx_registration.json (six ProRegTx a
//! regtest dashd v24.0.0-rc.3 built: `register_fund`, `register`,
//! `register_prepare` + `register_submit`, each regular and evonode) and
//! testdata/protx_update_registrar.json (four ProUpRegTx), generated by
//! testdata/oracle/dashd/gen_protx_vectors.py.
//!
//! "The same inputs" (MG-04 D2): each payload is rebuilt from the terms
//! dashd was given on dashd's own funded transaction, since the wallet
//! funds from its own coins, and only `inputsHash` (and so the signatures)
//! depends on the funding.

#![allow(non_snake_case)] // test names carry checklist ids

use std::str::FromStr;

use dashcore::blockdata::transaction::special_transaction::TransactionPayload;
use dashcore::blockdata::transaction::special_transaction::provider_registration::ProviderRegistrationPayload;
use dashcore::blockdata::transaction::special_transaction::provider_update_registrar::ProviderUpdateRegistrarPayload;
use dashcore::hashes::Hash;
use dashcore::{Address, Network, ScriptBuf, Transaction};
use dw_protx::bls::parse_public_hex;
use dw_protx::params::collateral_amount;
use dw_protx::payloads::{
    CollateralSource, PlatformPorts, RegistrationSigner, RegistrationTerms, finalize_registration,
    finalize_update_registrar, registration_placeholder, registration_sign_message,
    registration_with_inputs, update_registrar_placeholder, update_registrar_with_inputs,
};
use dw_protx::rules::{
    self, ListedMasternode, check_registration, check_update_registrar, p2pkh_key_id,
};
use serde_json::Value;
use zeroize::Zeroizing;

const N: Network = Network::Regtest;

fn load(name: &str) -> Value {
    let path = format!("{}/../../../testdata/{name}", env!("CARGO_MANIFEST_DIR"));
    let doc: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).unwrap();
    assert_eq!(doc["network"], "regtest");
    assert!(
        doc["source"].as_str().unwrap().contains("v24.0.0-rc.3"),
        "the oracle is dashd rc.3"
    );
    doc
}

fn registrations() -> Vec<Value> {
    let cases = load("protx_registration.json")["cases"]
        .as_array()
        .unwrap()
        .clone();
    let kinds: Vec<&str> = cases.iter().map(|c| s(c, "kind")).collect();
    assert_eq!(
        kinds,
        [
            "fund_new_regular",
            "existing_regular",
            "prepared_regular",
            "fund_new_evo",
            "existing_evo",
            "prepared_evo"
        ]
    );
    cases
}

fn updates() -> Vec<Value> {
    load("protx_update_registrar.json")["cases"]
        .as_array()
        .unwrap()
        .clone()
}

fn s<'a>(c: &'a Value, key: &str) -> &'a str {
    c[key]
        .as_str()
        .unwrap_or_else(|| panic!("{key} is missing"))
}

fn address(text: &str) -> Address {
    Address::from_str(text).unwrap().require_network(N).unwrap()
}

fn key_id(text: &str) -> [u8; 20] {
    p2pkh_key_id(&address(text).script_pubkey()).expect("a P2PKH address")
}

fn secret_of(wif: &str) -> Zeroizing<[u8; 32]> {
    let secret = dw_uri::keyio::decode_secret(wif, N).expect("regtest WIF");
    assert!(secret.compressed);
    secret.key
}

fn tx_of(hex_tx: &str) -> Transaction {
    dashcore::consensus::deserialize(&hex::decode(hex_tx).unwrap()).unwrap()
}

fn registration_of(tx: &Transaction) -> ProviderRegistrationPayload {
    match &tx.special_transaction_payload {
        Some(TransactionPayload::ProviderRegistrationPayloadType(p)) => p.clone(),
        _ => panic!("not a ProRegTx"),
    }
}

fn update_of(tx: &Transaction) -> ProviderUpdateRegistrarPayload {
    match &tx.special_transaction_payload {
        Some(TransactionPayload::ProviderUpdateRegistrarPayloadType(p)) => p.clone(),
        _ => panic!("not a ProUpRegTx"),
    }
}

/// The terms of a case as dashd was given them (`protx register*`'s
/// arguments): nothing is read back from dashd's payload except the
/// existing collateral's outpoint, which the caller names.
fn terms(c: &Value) -> RegistrationTerms {
    let evo = s(c, "masternode_type") == "evo";
    let collateral = if s(c, "kind").starts_with("fund_new") {
        CollateralSource::FundNew {
            script: address(s(c, "collateral_address")).script_pubkey(),
            amount: collateral_amount(evo),
        }
    } else {
        CollateralSource::Existing(dashcore::OutPoint {
            txid: dashcore::Txid::from_str(s(c, "collateral_hash")).unwrap(),
            vout: c["collateral_index"].as_u64().unwrap() as u32,
        })
    };
    // `ParseFixedPoint(operatorReward, 2)` (rpc/evo.cpp:909-916).
    let reward = (s(c, "operator_reward").parse::<f64>().unwrap() * 100.0).round() as u16;
    let platform = evo.then(|| {
        let mut node_id = [0u8; 20];
        hex::decode_to_slice(s(c, "platform_node_id"), &mut node_id).unwrap();
        PlatformPorts {
            node_id,
            p2p_port: c["platform_p2p_port"].as_u64().unwrap() as u16,
            http_port: c["platform_http_port"].as_u64().unwrap() as u16,
        }
    });
    RegistrationTerms {
        evo,
        collateral,
        service: dw_protx::service::parse_service(s(c, "service"), N).unwrap(),
        owner_key_hash: key_id(s(c, "owner_address")),
        voting_key_hash: key_id(s(c, "voting_address")),
        operator_public_key: parse_public_hex(s(c, "operator_public")).unwrap(),
        operator_reward: reward,
        payout_script: address(s(c, "payout_address")).script_pubkey(),
        platform,
    }
}

/// `unsigned` with the placeholder of `terms` in place of its payload.
fn with_placeholder(tx: &Transaction, terms: &RegistrationTerms) -> Transaction {
    let mut unsigned = tx.clone();
    unsigned.special_transaction_payload = Some(
        TransactionPayload::ProviderRegistrationPayloadType(registration_placeholder(terms)),
    );
    unsigned
}

fn signer_of(c: &Value, terms: &RegistrationTerms) -> RegistrationSigner {
    match (&terms.collateral, s(c, "kind")) {
        (CollateralSource::FundNew { script, amount }, _) => RegistrationSigner::FundNew {
            script: script.clone(),
            amount: *amount,
        },
        (_, kind) if kind.starts_with("prepared") => {
            let sig: [u8; 65] = hex::decode(s(c, "signature_hex"))
                .unwrap()
                .try_into()
                .unwrap();
            RegistrationSigner::Signed(sig)
        }
        _ => RegistrationSigner::Collateral {
            secret: secret_of(s(c, "collateral_wif")),
            network: N,
        },
    }
}

/// Every flow's payload, rebuilt from dashd's terms on dashd's transaction,
/// equals dashd's byte for byte: version 2, the type, the fund-new output
/// index after dashd's BIP69 sort, the payee, the inputs hash and the
/// collateral signature (RFC 6979 on both sides, or the pasted one).
#[test]
fn test_MG04_registrations_equal_dashd() {
    for c in registrations() {
        let tx = tx_of(s(&c, "tx_hex"));
        assert_eq!(tx.txid().to_string(), s(&c, "pro_tx_hash"));
        let want = registration_of(&tx);
        assert_eq!(
            want.version,
            2,
            "{}: dashd builds version 2 here",
            s(&c, "kind")
        );
        let t = terms(&c);
        let got = finalize_registration(&with_placeholder(&tx, &t), &signer_of(&c, &t)).unwrap();
        assert_eq!(
            got,
            TransactionPayload::ProviderRegistrationPayloadType(want.clone()),
            "{} payload",
            s(&c, "kind")
        );
        assert_eq!(
            dashcore::consensus::serialize(&got),
            dashcore::consensus::serialize(&TransactionPayload::ProviderRegistrationPayloadType(
                want
            )),
            "{} bytes",
            s(&c, "kind")
        );
    }
}

/// `register_prepare`: the wallet's prepared payload (the placeholder of
/// dashd's terms with the inputs hash of dashd's prepared transaction)
/// equals dashd's, and its sign message is `signMessage` byte for byte; the
/// pasted `signmessage` signature finishes it into dashd's submitted
/// payload.
#[test]
fn test_MG04_prepare_sign_message_equals_register_prepare() {
    for c in registrations()
        .into_iter()
        .filter(|c| s(c, "kind").starts_with("prepared"))
    {
        let prepared = tx_of(s(&c, "prepared_tx_hex"));
        let dashd_prepared = registration_of(&prepared);
        assert!(dashd_prepared.signature.is_empty());
        let t = terms(&c);
        let ours = registration_with_inputs(&with_placeholder(&prepared, &t)).unwrap();
        assert_eq!(ours, dashd_prepared, "{}", s(&c, "kind"));
        let message = registration_sign_message(&ours, N).unwrap();
        assert_eq!(message.as_bytes(), s(&c, "sign_message").as_bytes());
        assert_eq!(s(&c, "sign_address"), s(&c, "collateral_address"));
        let collateral = address(s(&c, "collateral_address")).script_pubkey();
        let mut signed = ours.clone();
        signed.signature = hex::decode(s(&c, "signature_hex")).unwrap();
        assert_eq!(
            rules::check_external_collateral(
                &signed,
                &collateral,
                Some(collateral_amount(t.evo)),
                N
            ),
            Ok(())
        );
        let submitted = registration_of(&tx_of(s(&c, "tx_hex")));
        assert_eq!(
            signed,
            submitted,
            "{}: register_submit only inserts the signature",
            s(&c, "kind")
        );
    }
}

/// The rules module accepts every payload dashd built (empty list), and
/// returns Core's reason for each mutant the brief names (MG-04 §7).
#[test]
fn test_MG04_rules_accept_dashd_and_name_mutants() {
    for c in registrations() {
        let tx = tx_of(s(&c, "tx_hex"));
        let p = registration_of(&tx);
        let kind = s(&c, "kind");
        let existing_script = (!kind.starts_with("fund_new"))
            .then(|| ScriptBuf::from_bytes(hex::decode(s(&c, "collateral_script_hex")).unwrap()));
        let value = existing_script
            .as_ref()
            .map(|_| (c["collateral_value"].as_f64().unwrap() * 1e8).round() as u64);
        let existing = existing_script.as_ref().map(|s| (s, value));
        assert_eq!(
            check_registration(&tx, &p, existing, &[], N),
            Ok(()),
            "{kind}"
        );

        // The payee swapped for the owner's address.
        let mut m = p.clone();
        m.script_payout = address(s(&c, "owner_address")).script_pubkey();
        assert_eq!(
            check_registration(&tx, &m, existing, &[], N),
            Err("bad-protx-payee-reuse"),
            "{kind}"
        );
        if kind.starts_with("fund_new") {
            // The collateral index off by one.
            for vout in [
                p.collateral_outpoint.vout + 1,
                p.collateral_outpoint.vout ^ 1,
            ] {
                let mut m = p.clone();
                m.collateral_outpoint.vout = vout;
                let r = check_registration(&tx, &m, existing, &[], N);
                assert!(
                    matches!(
                        r,
                        Err("bad-protx-collateral-index" | "bad-protx-collateral")
                    ),
                    "{kind}: {r:?}"
                );
            }
        } else {
            // The collateral key signs the message without its payload hash
            // (a signature over another hash).
            let secret = secret_of(s(&c, "collateral_wif"));
            let mut m = p.clone();
            let message = registration_sign_message(&m, N).unwrap();
            let short = message.rsplit_once('|').unwrap().0;
            m.signature = dw_protx::payloads::sign_message_compact(&secret, short)
                .unwrap()
                .to_vec();
            assert_eq!(
                check_registration(&tx, &m, existing, &[], N),
                Err("bad-protx-sig"),
                "{kind}"
            );
        }
        // Another inputs set.
        let mut other = tx.clone();
        other.input[0].previous_output.vout ^= 1;
        assert_eq!(
            rules::check_inputs_hash(&other, p.inputs_hash.to_byte_array()),
            Err("bad-protx-inputs-hash")
        );
        // A listed masternode with the same operator key.
        let listed = ListedMasternode {
            pro_tx_hash: [0xee; 32],
            service: None,
            operator_public_key: *p.operator_public_key.as_ref(),
            voting_key_id: [0; 20],
            platform_node_id: None,
            collateral: None,
        };
        assert_eq!(
            check_registration(&tx, &p, existing, &[listed], N),
            Err("bad-protx-dup-key"),
            "{kind}"
        );
    }
}

/// ProUpRegTx: rebuilt from the call's arguments (an empty argument keeps
/// the masternode's value, which `protx_info_before` shows) and signed with
/// the owner key, it equals dashd's byte for byte; the rules accept it and
/// refuse a signature over the payload hash with the signature included.
#[test]
fn test_MG04_update_registrars_equal_dashd() {
    let cases = updates();
    let kinds: Vec<&str> = cases.iter().map(|c| s(c, "kind")).collect();
    assert_eq!(
        kinds,
        [
            "voting_regular",
            "payout_regular",
            "operator_regular",
            "all_evo"
        ]
    );
    for c in cases {
        let tx = tx_of(s(&c, "tx_hex"));
        let want = update_of(&tx);
        assert_eq!(want.version, 2);
        assert_eq!(want.pro_tx_hash.to_string(), s(&c, "pro_tx_hash"));
        let mut unsigned = tx.clone();
        unsigned.special_transaction_payload = Some(
            TransactionPayload::ProviderUpdateRegistrarPayloadType(update_registrar_placeholder(
                want.pro_tx_hash,
                parse_public_hex(s(&c, "operator_public")).unwrap(),
                key_id(s(&c, "voting_address")),
                address(s(&c, "payout_address")).script_pubkey(),
            )),
        );
        // What the vault's owner signer is handed: dashd's payload without
        // its signature, held to the rules a placeholder can be (D11).
        let committed = update_registrar_with_inputs(&unsigned).unwrap();
        assert_eq!(
            committed,
            ProviderUpdateRegistrarPayload {
                payload_sig: Vec::new(),
                ..want.clone()
            }
        );
        let owner = secret_of(s(&c, "owner_wif"));
        let owner_id = key_id(s(&c["protx_info_before"]["state"], "ownerAddress"));
        assert_eq!(
            rules::check_update_registrar_terms(&committed, owner_id, None, &[]),
            Ok(())
        );
        let got = finalize_update_registrar(&unsigned, &owner).unwrap();
        assert_eq!(
            got,
            TransactionPayload::ProviderUpdateRegistrarPayloadType(want.clone()),
            "{}",
            s(&c, "kind")
        );
        assert_eq!(
            check_update_registrar(&tx, &want, owner_id, None, &[]),
            Ok(()),
            "{}",
            s(&c, "kind")
        );
        let mut m = want.clone();
        let mut over_sig = want.clone();
        over_sig.payload_sig = vec![0; 65];
        let hash =
            dashcore::hashes::sha256d::Hash::hash(&dashcore::consensus::serialize(&over_sig));
        m.payload_sig = dw_protx::payloads::sign_hash_compact(&owner, hash.as_byte_array())
            .unwrap()
            .to_vec();
        assert_eq!(
            check_update_registrar(&tx, &m, owner_id, None, &[]),
            Err("bad-protx-sig")
        );
        // The payee swapped for the new voting key's address.
        let mut m = want.clone();
        m.script_payout = address(s(&c, "voting_address")).script_pubkey();
        assert_eq!(
            check_update_registrar(&tx, &m, owner_id, None, &[]),
            Err("bad-protx-payee-reuse")
        );
    }
}
